import React, { useState } from "react";
import "./Sidebar.css";
import { FaHome, FaBook, FaGamepad, FaComments, FaUser } from "react-icons/fa";

function Sidebar() {
  const [open, setOpen] = useState(false);

  return (
    <aside
      className={`sidebar-container ${open ? "expanded" : "collapsed"}`}
      onMouseEnter={() => setOpen(true)}
      onMouseLeave={() => setOpen(false)}
    >
      <div className="sidebar-logo">
        {open ? "SciHub" : "S"}
      </div>

      <nav className="sidebar-nav">
        <button onClick={() => (window.location.href = "/dashboard")}>
          <FaHome className="icon" />
          {open && <span>Dashboard</span>}
        </button>

        <button onClick={() => (window.location.href = "/resources")}>
          <FaBook className="icon" />
          {open && <span>Resources</span>}
        </button>

        <button onClick={() => (window.location.href = "/games")}>
          <FaGamepad className="icon" />
          {open && <span>Games</span>}
        </button>

        <button onClick={() => (window.location.href = "/qa")}>
          <FaComments className="icon" />
          {open && <span>Q & A</span>}
        </button>

        <button onClick={() => (window.location.href = "/account")}>
          <FaUser className="icon" />
          {open && <span>Account</span>}
        </button>
      </nav>
    </aside>
  );
}

export default Sidebar;
